import torch
from torch import Tensor
from torch.utils.data import DataLoader, IterableDataset, get_worker_info

from src.mythosmini.config import FINEWEB_CONFIG, FINEWEB_DATASET, LOADER_CHUNK_SEQUENCES
from src.mythosmini.data.packing import pack_token_stream, quality_passes


def stream_fineweb_documents(
    quality_percent: float, shard_index: int, shard_count: int
) -> Iterator[str]:
    from datasets import load_dataset

    dataset: Any = load_dataset(FINEWEB_DATASET, name=FINEWEB_CONFIG, split="train", streaming=True)
    if shard_count > 1:
        dataset = dataset.shard(num_shards=shard_count, index=shard_index)
    for record in dataset:
        if quality_passes(int(record["int_score"]), str(record["id"]), quality_percent):
            yield str(record["text"])


class PackedFineweb(IterableDataset[Tensor]):
    def __init__(self, quality_percent: float, seq_len: int) -> None:
        super().__init__()
        self.quality_percent = quality_percent
        self.seq_len = seq_len

    def __iter__(self) -> Iterator[Tensor]:
        worker = get_worker_info()
        shard_index = worker.id if worker is not None else 0
        shard_count = worker.num_workers if worker is not None else 1
        documents = stream_fineweb_documents(self.quality_percent, shard_index, shard_count)
        return pack_token_stream(documents, self.seq_len)


def build_dataloader(quality_percent: float, seq_len: int, num_workers: int) -> DataLoader[Tensor]:
    dataset = PackedFineweb(quality_percent, seq_len)
    return DataLoader(
        dataset,
        batch_size=LOADER_CHUNK_SEQUENCES,
        num_workers=num_workers,
        pin_memory=torch.cuda.is_available(),
        prefetch_factor=4 if num_workers > 0 else None,
        persistent_workers=num_workers > 0,
        drop_last=True,
    )

import math
import time
from collections.abc import Callable
from dataclasses import dataclass

import torch

from src.mythosmini.config import OOM_BATCH_DECREMENT
from src.mythosmini.hardware.detect import DeviceInfo, refresh_free_memory

MEMORY_SAFETY_FRACTION = 0.8
PROBE_STEPS = 3
MIN_THROUGHPUT_GAIN = 1.02


@dataclass(frozen=True)
class BatchPlan:
    micro_batch: int
    grad_accum: int

    @property
    def effective_batch(self) -> int:
        return self.micro_batch * self.grad_accum


def shrink_after_oom(plan: BatchPlan) -> BatchPlan:
    new_micro = max(1, plan.micro_batch - OOM_BATCH_DECREMENT)
    new_accum = max(1, math.ceil(plan.effective_batch / new_micro))
    return BatchPlan(micro_batch=new_micro, grad_accum=new_accum)


def time_probe_steps(step_fn: Callable[[int], None], batch_size: int, device: str) -> float:
    step_fn(batch_size)
    if device == "cuda":
        torch.cuda.synchronize()
    started = time.perf_counter()
    for _ in range(PROBE_STEPS):
        step_fn(batch_size)
    if device == "cuda":
        torch.cuda.synchronize()
    return (time.perf_counter() - started) / PROBE_STEPS


def probe_throughput(
    step_fn: Callable[[int], None], batch_size: int, seq_len: int, device: str
) -> float | None:
    try:
        seconds = time_probe_steps(step_fn, batch_size, device)
    except torch.OutOfMemoryError:
        if device == "cuda":
            torch.cuda.empty_cache()
        return None
    return batch_size * seq_len / seconds


def memory_allows_growth(info: DeviceInfo, baseline_free: int) -> bool:
    if info.device != "cuda":
        return True
    return refresh_free_memory(info) > baseline_free * (1.0 - MEMORY_SAFETY_FRACTION)


def autotune_batch_size(
    step_fn: Callable[[int], None], seq_len: int, info: DeviceInfo
) -> BatchPlan:
    baseline_free = refresh_free_memory(info)
    best_batch = 1
    best_throughput = 0.0
    candidate = 8 if info.device == "cuda" else 1
    while True:
        throughput = probe_throughput(step_fn, candidate, seq_len, info.device)
        if throughput is None:
            break
        if throughput > best_throughput * MIN_THROUGHPUT_GAIN:
            best_batch = candidate
            best_throughput = throughput
        elif candidate > best_batch:
            break
        if not memory_allows_growth(info, baseline_free):
            break
        if info.device == "cpu" and candidate >= 8:
            break
        candidate *= 2
    return BatchPlan(micro_batch=best_batch, grad_accum=1)

import os
from dataclasses import dataclass

import torch


@dataclass(frozen=True)
class DeviceInfo:
    device: str
    name: str
    total_memory_bytes: int
    free_memory_bytes: int
    supports_bf16: bool
    cpu_threads: int


def detect_device() -> DeviceInfo:
    cpu_threads = os.cpu_count() or 1
    if torch.cuda.is_available():
        free_bytes, total_bytes = torch.cuda.mem_get_info()
        properties = torch.cuda.get_device_properties(0)
        return DeviceInfo(
            device="cuda",
            name=properties.name,
            total_memory_bytes=total_bytes,
            free_memory_bytes=free_bytes,
            supports_bf16=torch.cuda.is_bf16_supported(),
            cpu_threads=cpu_threads,
        )
    return DeviceInfo(
        device="cpu",
        name="cpu",
        total_memory_bytes=0,
        free_memory_bytes=0,
        supports_bf16=False,
        cpu_threads=cpu_threads,
    )


def refresh_free_memory(info: DeviceInfo) -> int:
    if info.device != "cuda":
        return 0
    free_bytes, _ = torch.cuda.mem_get_info()
    return int(free_bytes)


def autocast_dtype(info: DeviceInfo) -> torch.dtype:
    if info.device == "cuda" and info.supports_bf16:
        return torch.bfloat16
    return torch.float32


def describe_device(info: DeviceInfo) -> str:
    if info.device == "cpu":
        return f"cpu ({info.cpu_threads} threads)"
    total_gb = info.total_memory_bytes / 1024**3
    free_gb = info.free_memory_bytes / 1024**3
    return f"{info.name} ({free_gb:.1f} GiB free of {total_gb:.1f} GiB, bf16={info.supports_bf16})"

import os
import queue
import threading
from pathlib import Path
from typing import Any

import torch


def cpu_clone_state(state: dict[str, Any]) -> dict[str, Any]:
    cloned: dict[str, Any] = {}
    for key, value in state.items():
        if isinstance(value, torch.Tensor):
            cloned[key] = value.detach().to("cpu", copy=True)
        elif isinstance(value, dict):
            cloned[key] = cpu_clone_state(value)
        elif isinstance(value, list):
            cloned[key] = [
                item.detach().to("cpu", copy=True) if isinstance(item, torch.Tensor) else item
                for item in value
            ]
        else:
            cloned[key] = value
    return cloned


class BackgroundSaver:
    def __init__(self) -> None:
        self.tasks: queue.Queue[tuple[dict[str, Any], Path] | None] = queue.Queue()
        self.worker = threading.Thread(target=self.drain, daemon=True)
        self.worker.start()

    def drain(self) -> None:
        while True:
            task = self.tasks.get()
            if task is None:
                self.tasks.task_done()
                return
            payload, destination = task
            temp_path = destination.with_suffix(".tmp")
            torch.save(payload, temp_path)
            os.replace(temp_path, destination)
            self.tasks.task_done()

    def submit(self, payload: dict[str, Any], destination: Path) -> None:
        destination.parent.mkdir(parents=True, exist_ok=True)
        self.tasks.put((cpu_clone_state(payload), destination))

    def wait_for_all(self) -> None:
        self.tasks.join()

    def shutdown(self) -> None:
        self.tasks.put(None)
        self.worker.join()

import zlib
from collections.abc import Iterator

import torch
from torch import Tensor

from src.mythosmini.config import EOS_TOKEN_ID


def byte_tokenize(text: str) -> list[int]:
    return [*text.encode("utf-8"), EOS_TOKEN_ID]


def pack_token_stream(documents: Iterator[str], seq_len: int) -> Iterator[Tensor]:
    if seq_len < 2:
        raise ValueError(f"seq_len must be at least 2, got {seq_len}")
    block_len = seq_len + 1
    buffer: list[int] = []
    for document in documents:
        buffer.extend(byte_tokenize(document))
        while len(buffer) >= block_len:
            block = buffer[:block_len]
            buffer = buffer[block_len:]
            yield torch.tensor(block, dtype=torch.long)


def quality_passes(int_score: int, doc_id: str, percent: float) -> bool:
    if int_score == 5:
        threshold = percent / 0.12
    elif int_score == 4:
        if percent <= 0.12:
            return False
        threshold = (percent - 0.12) / 0.28
    elif int_score == 3:
        if percent <= 0.40:
            return False
        threshold = (percent - 0.40) / 0.60
    else:
        return False

    if threshold >= 1.0:
        return True
    if threshold <= 0.0:
        return False

    h = (zlib.adler32(doc_id.encode("utf-8")) & 0xFFFFFFFF) / 0xFFFFFFFF
    return h < threshold

import math

import torch
from torch import Tensor

PARALLEL_THRESHOLD = 1e-4


def slerp_tensor(a: Tensor, b: Tensor, t: float) -> Tensor:
    if a.shape != b.shape:
        raise ValueError(f"shape mismatch: {tuple(a.shape)} vs {tuple(b.shape)}")
    a32 = a.float().flatten()
    b32 = b.float().flatten()
    dot = float(torch.dot(a32, b32).item())
    if dot < 0.0:
        b32 = -b32
        dot = -dot
    norm_a = float(torch.linalg.vector_norm(a32).item())
    norm_b = float(torch.linalg.vector_norm(b32).item())
    if norm_a == 0.0 or norm_b == 0.0:
        return torch.lerp(a32, b32, t).reshape(a.shape).to(a.dtype)
    cosine = max(-1.0, min(1.0, dot / (norm_a * norm_b)))
    theta = math.acos(cosine)
    if theta < PARALLEL_THRESHOLD:
        return torch.lerp(a32, b32, t).reshape(a.shape).to(a.dtype)
    sin_theta = math.sin(theta)
    weight_a = math.sin((1.0 - t) * theta) / sin_theta
    weight_b = math.sin(t * theta) / sin_theta
    return (weight_a * a32 + weight_b * b32).reshape(a.shape).to(a.dtype)


def slerp_state_dicts(
    state_a: dict[str, Tensor], state_b: dict[str, Tensor], t: float
) -> dict[str, Tensor]:
    if state_a.keys() != state_b.keys():
        raise ValueError("state dicts have different keys, cannot merge")
    merged: dict[str, Tensor] = {}
    for key, tensor_a in state_a.items():
        tensor_b = state_b[key]
        if tensor_a.is_floating_point() and tensor_b.is_floating_point():
            merged[key] = slerp_tensor(tensor_a, tensor_b, t)
        else:
            merged[key] = tensor_a.clone()
    return merged

import math
from collections.abc import Callable
from dataclasses import dataclass

from torch import Tensor

from src.mythosmini.benchmarks.runner import BenchmarkScores
from src.mythosmini.config import SLERP_MAX_GENERATIONS, SLERP_T_SWEEP, SLERP_TOP_K
from src.mythosmini.merging.slerp import slerp_state_dicts

STALL_GENERATIONS = 3
SHARED_STEP_SKIP_RATIO = 0.5


@dataclass
class MergeCandidate:
    name: str
    state: dict[str, Tensor]
    steps: frozenset[int]
    scores: BenchmarkScores


Evaluator = Callable[[str, dict[str, Tensor]], BenchmarkScores]


def improves_any_category(child: BenchmarkScores, best: BenchmarkScores) -> bool:
    return child.blimp > best.blimp or child.arc > best.arc or child.wiki_ppl < best.wiki_ppl


def category_best(candidates: list[MergeCandidate]) -> BenchmarkScores:
    return BenchmarkScores(
        wiki_ppl=min(candidate.scores.wiki_ppl for candidate in candidates),
        blimp=max(candidate.scores.blimp for candidate in candidates),
        arc=max(candidate.scores.arc for candidate in candidates),
    )


def normalized_averages(candidates: list[MergeCandidate]) -> list[float]:
    blimps = [candidate.scores.blimp for candidate in candidates]
    arcs = [candidate.scores.arc for candidate in candidates]
    wiki_logs = [-math.log(max(candidate.scores.wiki_ppl, 1e-9)) for candidate in candidates]

    def normalize(values: list[float]) -> list[float]:
        low, high = min(values), max(values)
        if high == low:
            return [0.5] * len(values)
        return [(value - low) / (high - low) for value in values]

    columns = [normalize(blimps), normalize(arcs), normalize(wiki_logs)]
    return [sum(column[index] for column in columns) / 3.0 for index in range(len(candidates))]


def select_diverse(candidates: list[MergeCandidate], keep: int) -> list[MergeCandidate]:
    if not candidates:
        return []
    diverse: dict[str, MergeCandidate] = {}
    wiki_best = min(candidates, key=lambda c: c.scores.wiki_ppl)
    diverse[wiki_best.name] = wiki_best
    blimp_best = max(candidates, key=lambda c: c.scores.blimp)
    diverse[blimp_best.name] = blimp_best
    arc_best = max(candidates, key=lambda c: c.scores.arc)
    diverse[arc_best.name] = arc_best
    averages = normalized_averages(candidates)
    order = sorted(range(len(candidates)), key=lambda i: averages[i], reverse=True)
    for index in order:
        if len(diverse) >= keep:
            break
        candidate = candidates[index]
        if candidate.name not in diverse:
            diverse[candidate.name] = candidate
    final_list = list(diverse.values())
    final_averages = normalized_averages(final_list)
    final_order = sorted(range(len(final_list)), key=lambda i: final_averages[i], reverse=True)
    return [final_list[index] for index in final_order]


def build_centroid_merge(
    parents: list[MergeCandidate], generation: int, evaluate: Evaluator
) -> MergeCandidate | None:
    if len(parents) < 3:
        return None
    a, b, c = parents[0], parents[1], parents[2]
    state_ab = slerp_state_dicts(a.state, b.state, 0.5)
    name_abc = f"gen{generation}_centroid_{a.name}+{b.name}+{c.name}"
    state_abc = slerp_state_dicts(state_ab, c.state, 0.33)
    scores = evaluate(name_abc, state_abc)
    return MergeCandidate(
        name=name_abc, state=state_abc, steps=a.steps | b.steps | frozenset(c.steps), scores=scores
    )


def shares_too_many_steps(a: MergeCandidate, b: MergeCandidate) -> bool:
    if not a.steps or not b.steps:
        return False
    highest_a, highest_b = max(a.steps), max(b.steps)
    if highest_a == 0 or highest_b == 0:
        return False
    return min(highest_a, highest_b) / max(highest_a, highest_b) > SHARED_STEP_SKIP_RATIO


def merge_pair(
    a: MergeCandidate, b: MergeCandidate, t: float, generation: int, evaluate: Evaluator
) -> MergeCandidate:
    name = f"gen{generation}_{a.name}+{b.name}@t{t:.2f}"
    state = slerp_state_dicts(a.state, b.state, t)
    scores = evaluate(name, state)
    return MergeCandidate(name=name, state=state, steps=a.steps | b.steps, scores=scores)


def eligible_pairs(
    parents: list[MergeCandidate], generation: int
) -> list[tuple[MergeCandidate, MergeCandidate]]:
    all_pairs = [
        (parents[first_index], parents[second_index])
        for first_index in range(len(parents))
        for second_index in range(first_index + 1, len(parents))
    ]
    if generation != 0:
        return all_pairs
    filtered = []
    for a, b in all_pairs:
        is_outstanding_a = a.scores.blimp > 58 or a.scores.arc > 30 or a.scores.wiki_ppl < 4.5
        is_outstanding_b = b.scores.blimp > 58 or b.scores.arc > 30 or b.scores.wiki_ppl < 4.5
        if is_outstanding_a and is_outstanding_b:
            filtered.append((a, b))
            continue
        if not shares_too_many_steps(a, b):
            filtered.append((a, b))
    return filtered if filtered else all_pairs


def build_generation(
    parents: list[MergeCandidate], generation: int, evaluate: Evaluator
) -> list[MergeCandidate]:
    children: list[MergeCandidate] = []
    for first, second in eligible_pairs(parents, generation):
        for t in SLERP_T_SWEEP:
            children.append(merge_pair(first, second, t, generation, evaluate))
    wiki_best = min(parents, key=lambda c: c.scores.wiki_ppl)
    arc_best = max(parents, key=lambda c: c.scores.arc)
    blimp_best = max(parents, key=lambda c: c.scores.blimp)
    for t in (0.33, 0.5, 0.66):
        children.append(merge_pair(wiki_best, arc_best, t, generation, evaluate))
        children.append(merge_pair(wiki_best, blimp_best, t, generation, evaluate))
        children.append(merge_pair(arc_best, blimp_best, t, generation, evaluate))
    centroid = build_centroid_merge(parents, generation, evaluate)
    if centroid:
        children.append(centroid)
    return children


def aggregate_score(
    scores: BenchmarkScores,
    blimp_ref: tuple[float, float],
    arc_ref: tuple[float, float],
    wiki_log_ref: tuple[float, float],
) -> float:
    def normalize(val: float, ref: tuple[float, float]) -> float:
        if ref[1] == ref[0]:
            return 0.5
        return (val - ref[0]) / (ref[1] - ref[0])

    blimp_n = normalize(scores.blimp, blimp_ref)
    arc_n = normalize(scores.arc, arc_ref)
    wiki_log = -math.log(max(scores.wiki_ppl, 1e-9))
    wiki_n = normalize(wiki_log, wiki_log_ref)
    return (blimp_n + arc_n + wiki_n) / 3.0


def run_tournament(
    seeds: list[MergeCandidate],
    evaluate: Evaluator,
    log: Callable[[str], None],
) -> MergeCandidate:
    if not seeds:
        raise ValueError("tournament needs at least one seed candidate")

    blimps = [s.scores.blimp for s in seeds]
    arcs = [s.scores.arc for s in seeds]
    wiki_logs = [-math.log(max(s.scores.wiki_ppl, 1e-9)) for s in seeds]
    b_ref = (min(blimps), max(blimps))
    a_ref = (min(arcs), max(arcs))
    w_ref = (min(wiki_logs), max(wiki_logs))

    population = select_diverse(seeds, SLERP_TOP_K)
    best_overall = population[0]
    best_score = aggregate_score(best_overall.scores, b_ref, a_ref, w_ref)
    best_average = max(normalized_averages(population))
    stalled = 0

    for generation in range(SLERP_MAX_GENERATIONS):
        if len(population) < 2:
            log(f"tournament stopped: single candidate after generation {generation}")
            break
        previous_best = category_best(population)
        children = build_generation(population, generation, evaluate)
        if not children:
            log(f"tournament stopped: no eligible pairs in generation {generation}")
            break

        for child in children:
            score = aggregate_score(child.scores, b_ref, a_ref, w_ref)
            if score > best_score:
                best_score = score
                best_overall = child

        if not any(improves_any_category(child.scores, previous_best) for child in children):
            log(f"tournament stopped: generation {generation} children worse in all categories")
            break

        population = select_diverse(population + children, SLERP_TOP_K)
        current_best = max(normalized_averages(population))
        stalled = stalled + 1 if current_best <= best_average else 0
        best_average = max(best_average, current_best)
        log(f"generation {generation}: population {len(population)}, stalled {stalled}")
        if stalled >= STALL_GENERATIONS:
            log("tournament stopped: no improvement for three generations")
            break
    return best_overall

from dataclasses import dataclass

import torch

from src.mythosmini.benchmarks.arc import ArcQuestion, arc_accuracy, load_arc_questions
from src.mythosmini.benchmarks.blimp import blimp_accuracy, load_blimp_pairs
from src.mythosmini.benchmarks.wikitext import byte_perplexity, load_wikitext_bytes
from src.mythosmini.hardware.autotune import autotune_batch_size
