def load_blimp_pairs(
    pairs_per_subtask: int = BLIMP_PAIRS_PER_SUBTASK,
) -> dict[str, list[tuple[str, str]]]:
    from datasets import get_dataset_config_names, load_dataset

    subtasks: dict[str, list[tuple[str, str]]] = {}
    for config_name in sorted(get_dataset_config_names(BLIMP_DATASET)):
        dataset = load_dataset(BLIMP_DATASET, name=config_name, split="train")
        pairs: list[tuple[str, str]] = []
        for record in dataset:
            pairs.append((str(record["sentence_good"]), str(record["sentence_bad"])))
            if len(pairs) >= pairs_per_subtask:
                break
        if pairs:
            subtasks[config_name] = pairs
    if not subtasks:
        raise ValueError(f"no blimp subtasks loaded from {BLIMP_DATASET}")
    return subtasks


def sentence_pair(sentence: str) -> ScoredPair:
    return ScoredPair(context=[EOS_TOKEN_ID], continuation=list(sentence.encode("utf-8")))


def blimp_accuracy(
    model: MythosMini,
    subtasks: dict[str, list[tuple[str, str]]],
    batch_size: int,
    device: str,
    dtype: torch.dtype,
) -> float:
    accuracies: list[float] = []
    for pairs in subtasks.values():
        scored: list[ScoredPair] = []
        for good, bad in pairs:
            scored.append(sentence_pair(good))
            scored.append(sentence_pair(bad))
        likelihoods = continuation_log_likelihoods(model, scored, batch_size, device, dtype)
        correct = sum(
            1 for index in range(len(pairs)) if likelihoods[2 * index] > likelihoods[2 * index + 1]
        )
        accuracies.append(correct / len(pairs))
    return 100.0 * sum(accuracies) / len(accuracies)

import urllib.error
import urllib.request
from pathlib import Path

from src.mythosmini.config import LEADERBOARD_URL
from src.mythosmini.leaderboard.entries import LeaderboardEntry, parse_leaderboard_html

FETCH_TIMEOUT_SECONDS = 30.0


def download_leaderboard_html(url: str = LEADERBOARD_URL) -> str:
    request = urllib.request.Request(url, headers={"User-Agent": "mythosmini-trainer"})
    with urllib.request.urlopen(request, timeout=FETCH_TIMEOUT_SECONDS) as response:
        body: bytes = response.read()
    return body.decode("utf-8")


def fetch_leaderboard(cache_path: Path, url: str = LEADERBOARD_URL) -> list[LeaderboardEntry]:
    try:
        html = download_leaderboard_html(url)
    except (urllib.error.URLError, TimeoutError, OSError) as error:
        if cache_path.is_file():
            print(f"leaderboard fetch failed ({error}); using cached copy at {cache_path}")
            return parse_leaderboard_html(cache_path.read_text(encoding="utf-8"))
        print(f"leaderboard fetch failed ({error}); placements will be unavailable")
        return []
    cache_path.parent.mkdir(parents=True, exist_ok=True)
    cache_path.write_text(html, encoding="utf-8")
    return parse_leaderboard_html(html)

import re
from dataclasses import dataclass

NAME_PATTERN = re.compile(r"name:\s*'([^']*)'")
PARAMS_PATTERN = re.compile(r"params:\s*'([^']*)'")
METRIC_PATTERNS = {
    "blimp": re.compile(r"blimp:\s*(null|[-0-9.eE+]+)"),
    "arc": re.compile(r"arc:\s*(null|[-0-9.eE+]+)"),
    "wiki": re.compile(r"wiki:\s*(null|[-0-9.eE+]+)"),
}
MODELS_ARRAY_PATTERN = re.compile(r"const\s+models\s*=\s*\[")


@dataclass(frozen=True)
class LeaderboardEntry:
    name: str
    params: float
    blimp: float | None
    arc: float | None
    wiki: float | None


def parse_params_text(text: str) -> float:
    cleaned = text.strip().upper().replace(",", "")
    if not cleaned:
        raise ValueError(f"expected a parameter count like '1M', got {text!r}")
    multipliers = {"B": 1e9, "M": 1e6, "K": 1e3}
    suffix = cleaned[-1]
    if suffix in multipliers:
        return float(cleaned[:-1]) * multipliers[suffix]
    return float(cleaned)


def extract_models_block(html: str) -> str:
    match = MODELS_ARRAY_PATTERN.search(html)
    if match is None:
        raise ValueError("expected 'const models = [' in leaderboard html, not found")
    depth = 0
    for index in range(match.end() - 1, len(html)):
        char = html[index]
        if char == "[":
            depth += 1
        elif char == "]":
            depth -= 1
            if depth == 0:
                return html[match.end() : index]
    raise ValueError("unterminated models array in leaderboard html")


def split_entry_blocks(models_block: str) -> list[str]:
    blocks: list[str] = []
    depth = 0
    start = -1
    for index, char in enumerate(models_block):
        if char == "{":
            if depth == 0:
                start = index
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0 and start >= 0:
                blocks.append(models_block[start : index + 1])
    return blocks


def parse_metric(block: str, key: str) -> float | None:
    match = METRIC_PATTERNS[key].search(block)
    if match is None or match.group(1) == "null":
        return None
    return float(match.group(1))


def parse_entry_block(block: str) -> LeaderboardEntry | None:
    name_match = NAME_PATTERN.search(block)
    params_match = PARAMS_PATTERN.search(block)
    if name_match is None or params_match is None:
        return None
    return LeaderboardEntry(
        name=name_match.group(1),
        params=parse_params_text(params_match.group(1)),
        blimp=parse_metric(block, "blimp"),
        arc=parse_metric(block, "arc"),
        wiki=parse_metric(block, "wiki"),
    )


def parse_leaderboard_html(html: str) -> list[LeaderboardEntry]:
    blocks = split_entry_blocks(extract_models_block(html))
    entries = [entry for entry in map(parse_entry_block, blocks) if entry is not None]
    if not entries:
        raise ValueError("leaderboard html parsed to zero model entries")
    return entries

import math
from dataclasses import dataclass

from src.mythosmini.config import WIKI_PPL_CAP
from src.mythosmini.leaderboard.entries import LeaderboardEntry


@dataclass(frozen=True)
class WikiNormalization:
    min_log: float
    max_log: float


def build_wiki_normalization(entries: list[LeaderboardEntry]) -> WikiNormalization:
    logs = [
        math.log(min(entry.wiki, WIKI_PPL_CAP))
        for entry in entries
        if entry.wiki is not None and entry.wiki > 0
    ]
    if not logs:
        return WikiNormalization(min_log=0.0, max_log=0.0)
    return WikiNormalization(min_log=min(logs), max_log=max(logs))


def wiki_score(entry: LeaderboardEntry, norm: WikiNormalization) -> float | None:
    if entry.wiki is None or entry.wiki <= 0 or norm.min_log == norm.max_log:
        return None
    capped_log = math.log(min(entry.wiki, WIKI_PPL_CAP))
    normalized = 1.0 - (capped_log - norm.min_log) / (norm.max_log - norm.min_log)
    return max(0.0, min(1.0, normalized)) * 100.0


def overall_score(entry: LeaderboardEntry, norm: WikiNormalization) -> float:
    wiki = wiki_score(entry, norm)
    if entry.blimp is None and entry.arc is None and wiki is None:
        return -1.0
    blimp = entry.blimp if entry.blimp is not None else 0.0
    arc = entry.arc if entry.arc is not None else 0.0
    wiki_value = wiki if wiki is not None else 0.0
    return (blimp + arc + wiki_value) / 3.0


def efficiency_score(entry: LeaderboardEntry, norm: WikiNormalization) -> float:
    score = overall_score(entry, norm)
    if score < 0 or entry.params <= 0:
        return -1.0
    return score / math.log10(entry.params + 1.0)

from dataclasses import dataclass

from src.mythosmini.leaderboard.entries import LeaderboardEntry
from src.mythosmini.leaderboard.scoring import (
    build_wiki_normalization,
    efficiency_score,
    overall_score,
)


@dataclass(frozen=True)
class Placement:
    overall_rank: int
    efficiency_rank: int
    total_entries: int
    overall: float
    efficiency: float


def rank_of(value: float, others: list[float]) -> int:
    return 1 + sum(1 for other in others if other > value)


def compute_placement(
    candidate: LeaderboardEntry, leaderboard: list[LeaderboardEntry]
) -> Placement:
    combined = [*leaderboard, candidate]
    norm = build_wiki_normalization(combined)
    candidate_overall = overall_score(candidate, norm)
    candidate_efficiency = efficiency_score(candidate, norm)
    other_overalls = [overall_score(entry, norm) for entry in leaderboard]
    other_efficiencies = [efficiency_score(entry, norm) for entry in leaderboard]
    return Placement(
        overall_rank=rank_of(candidate_overall, other_overalls),
        efficiency_rank=rank_of(candidate_efficiency, other_efficiencies),
        total_entries=len(combined),
        overall=candidate_overall,
        efficiency=candidate_efficiency,
    )


def format_placement(label: str, placement: Placement) -> str:
    return (
        f"{label}: overall {placement.overall:.2f} "
        f"(rank {placement.overall_rank}/{placement.total_entries}), "
        f"efficiency {placement.efficiency:.2f} "
        f"(rank {placement.efficiency_rank}/{placement.total_entries})"
    )
